import re
from typing import List, Dict, Any, Optional

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    children = scope_nodes(doc, scope)
    products_table = None
    for node in children:
        if node.get('kind') == 'table' and 'Products' in node['title']:
            products_table = node
            break
    if not products_table:
        return []

    seen = set()
    result = []
    for row_idx, row in table_rows(products_table):
        prod = row.get('product')
        if prod and prod not in seen:
            seen.add(prod)
            result.append({"id": prod, "description": prod})
    return result

def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    children = scope_nodes(doc, scope)
    ledger_table = next((n for n in children if n.get('kind') == 'table' and 'Daily ledger' in n['title']), None)
    if ledger_table:
        max_day = 0.0
        for _, row in table_rows(ledger_table):
            try:
                day = float(row.get('day', 0))
                if day > max_day:
                    max_day = day
            except (ValueError, KeyError):
                pass
        return max_day if max_day > 0 else 14.0
    return 14.0

def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    children = scope_nodes(doc, scope)
    capacity = None
    for node in children:
        if node.get('kind') == 'text':
            match = re.search(r'Daily dispatch capacity:\s*([\d,]+(?:\.\d+)?)\s*kg', node.get('text', ''))
            if match:
                capacity = float(match.group(1))
    if capacity is not None:
        return {"capacity_kg": capacity}
    return {}

def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    result = []
    children = scope_nodes(doc, scope)

    products_table = None
    ledger_table = None
    orderbook_table = None
    for node in children:
        if node.get('kind') == 'table':
            title = node['title']
            if 'Products' in title:
                products_table = node
            elif 'Daily ledger' in title:
                ledger_table = node
            elif 'Order book' in title:
                orderbook_table = node

    if products_table:
        for row_idx, row in table_rows(products_table):
            prod = row.get('product')
            if not prod: continue
            open_stock = float(row.get('opening stock', 0))
            result.append({
                "id": f"opening_{prod}",
                "time": 0.0,
                "kind": "opening_stock",
                "entities": [prod],
                "fields": {"opening_stock": open_stock},
                "src": [[products_table['node_id'], row_idx, ['opening stock', 'product']]]
            })
            weight = float(row.get('kg per unit', 0))
            result.append({
                "id": f"weight_{prod}",
                "time": None,
                "kind": "weight",
                "entities": [prod],
                "fields": {"weight_kg": weight},
                "src": [[products_table['node_id'], row_idx, ['kg per unit', 'product']]]
            })

    if ledger_table:
        for row_idx, row in table_rows(ledger_table):
            prod = row.get('product')
            day = float(row.get('day', 0))
            if not prod: continue
            prod_qty = float(row.get('produced', 0))
            result.append({
                "id": f"prod_{day}_{prod}",
                "time": day,
                "kind": "production",
                "entities": [prod],
                "fields": {"produced": prod_qty},
                "src": [[ledger_table['node_id'], row_idx, ['produced', 'day', 'product']]]
            })
            ord_qty = float(row.get('ordered', 0))
            result.append({
                "id": f"ord_{day}_{prod}",
                "time": day,
                "kind": "order",
                "entities": [prod],
                "fields": {"ordered": ord_qty},
                "src": [[ledger_table['node_id'], row_idx, ['ordered', 'day', 'product']]]
            })

