        cols = orderbook_table['table']['columns']
        for row_idx, row in table_rows(orderbook_table):
            prod = row.get('product')
            if not prod: continue

            if 'planned production' in cols and 'ordered' in cols:
                day = float(row.get('day', 0))
                plan_qty = float(row.get('planned production', 0))
                src_cols = ['planned production', 'product', 'day']
                result.append({
                    "id": f"plan_prod_{day}_{prod}",
                    "time": day,
                    "kind": "planned_production",
                    "entities": [prod],
                    "fields": {"planned_production": plan_qty},
                    "src": [[orderbook_table['node_id'], row_idx, src_cols]]
                })
                ord_qty = float(row.get('ordered', 0))
                src_cols_2 = ['ordered', 'product', 'day']
                result.append({
                    "id": f"plan_ord_{day}_{prod}",
                    "time": day,
                    "kind": "planned_order",
                    "entities": [prod],
                    "fields": {"ordered": ord_qty},
                    "src": [[orderbook_table['node_id'], row_idx, src_cols_2]]
                })
