            elif 'day placed' in cols and 'units still open' in cols:
                day = float(row.get('day placed', 0))
                open_qty = float(row.get('units still open', 0))
                result.append({
                    "id": f"open_order_{day}_{prod}",
                    "time": day,
                    "kind": "open_order",
                    "entities": [prod],
                    "fields": {"units_still_open": open_qty},
                    "src": [[orderbook_table['node_id'], row_idx, ['units still open', 'day placed', 'product']]]
                })

    return result

def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    result = []
    children = scope_nodes(doc, scope)

    ledger_table = None
    events_list = None
    for node in children:
        if node.get('kind') == 'table' and 'Daily ledger' in node['title']:
            ledger_table = node
        elif node.get('kind') == 'list' and 'Events' in node['title']:
            events_list = node

    if ledger_table:
        for row_idx, row in table_rows(ledger_table):
            prod = row.get('product')
            day = float(row.get('day', 0))
            if not prod: continue
            shipped = float(row.get('shipped', 0))
            result.append({
                "time": day,
                "kind": "shipped",
                "entities": [prod],
                "value": shipped,
                "src": [[ledger_table['node_id'], row_idx, ['shipped', 'day', 'product']]]
            })
            backordered = float(row.get('backordered', 0))
            result.append({
                "time": day,
                "kind": "backordered",
                "entities": [prod],
                "value": backordered,
                "src": [[ledger_table['node_id'], row_idx, ['backordered', 'day', 'product']]]
            })
            stock = float(row.get('stock', 0))
            result.append({
                "time": day,
                "kind": "stock",
                "entities": [prod],
                "value": stock,
                "src": [[ledger_table['node_id'], row_idx, ['stock', 'day', 'product']]]
            })

    if events_list:
        lines = events_list.get('lines', [])
        for line_idx, line in enumerate(lines):
            match_day = re.search(r'Day\s+(\d+)', line)
            day = float(match_day.group(1)) if match_day else None
            if day is None: continue

            entities = []
            kind = "event"

            if 'runs out of stock' in line:
                m = re.search(r'([A-Z][\w\-]*) runs out of stock', line)
                if m:
                    entities.append(m.group(1))
                kind = "stock_run_out"
            elif 'dispatch capacity reached' in line:
                kind = "capacity_reached"
            elif 'fully backordered' in line:
                kind = "fully_backordered"
                m = re.search(r'([A-Z][\w\-]*) fully backordered', line)
                if m:
                    entities.append(m.group(1))
            elif 'backlog' in line and 'cleared' in line:
                m = re.search(r'([A-Z][\w\-]*) backlog was cleared', line)
                if m:
                    entities.append(m.group(1))
                    kind = "backlog_cleared"
                else:
                    kind = "backlogs_cleared"

            result.append({
                "time": day,
                "kind": kind,
                "entities": entities,
                "value": None,
                "src": [[events_list['node_id'], line_idx]]
            })

    return result


