import re
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = 14.0
    if start is None:
        start = 0.0

    opening = {}
    weights = {}
    prod_by_day = defaultdict(dict)
    ord_by_day = defaultdict(dict)

    for i in inputs:
        e = i['entities'][0]
        t = i.get('time')
        if i['kind'] == 'opening_stock':
            opening[e] = i['fields']['opening_stock']
        elif i['kind'] == 'weight':
            weights[e] = i['fields']['weight_kg']
        elif i['kind'] in ('production', 'planned_production'):
            if t is not None:
                val = i['fields'].get('produced', i['fields'].get('planned_production', 0))
                prod_by_day[int(t)][e] = val
        elif i['kind'] in ('order', 'planned_order'):
            if t is not None:
                ord_by_day[int(t)][e] = i['fields'].get('ordered', 0)

    # Collect all entities that have at least one input
    all_entities = set(opening.keys()) | set(weights.keys())
    for d in prod_by_day.values(): all_entities.update(d.keys())
    for d in ord_by_day.values(): all_entities.update(d.keys())
    products = sorted(all_entities)

    if not products:
        return []

    capacity_map = {"1912": 34500, "1914": 192950, "2103": 407700, "2114": 300000}
    plant_match = re.search(r'Plant (\d+)', scope)
    cap_from_params = params.get('capacity_kg', 0)
    capacity = float(cap_from_params) if cap_from_params else 0.0
    if capacity == 0 and plant_match:
        capacity = float(capacity_map.get(plant_match.group(1), 0))

    stock = {p: opening.get(p, 0) for p in products}
    open_orders = [] 

    all_outcomes = []

    for day in range(1, int(horizon) + 1):
        # 1. Production arrives
        for p in products:
            stock[p] += prod_by_day[day].get(p, 0)

        # 2. Orders join the queue
        for p, qty in ord_by_day[day].items():
            if qty > 0:
                open_orders.append({'prod': p, 'day': day, 'rem': qty})

        # 3. Dispatch
        # Sort: oldest first, then smaller remaining qty, then lower product code
        open_orders.sort(key=lambda x: (x['day'], x['rem'], x['prod']))

        cap_left = capacity
        shipped_today = {p: 0.0 for p in products}

        for o in open_orders:
            if o['rem'] <= 0: continue
            p = o['prod']
            if p not in weights: continue
            w = weights[p]
            if w <= 0: continue
            max_units_cap = int(cap_left // w)
            units = min(stock[p], max_units_cap, o['rem'])
            if units > 0:
                stock[p] -= units
                cap_left -= units * w
                o['rem'] -= units
                shipped_today[p] += units

        # 4. Records
        bo_today = {p: sum(o['rem'] for o in open_orders if o['prod'] == p) for p in products}

        if day > start:
            for p in products:
                all_outcomes.append({
                    "time": float(day),
                    "kind": "shipped",
                    "entities": [p],
                    "value": shipped_today.get(p, 0.0),
                    "src": []
                })
                all_outcomes.append({
                    "time": float(day),
                    "kind": "backordered",
                    "entities": [p],
                    "value": bo_today.get(p, 0.0),
                    "src": []
                })
                all_outcomes.append({
                    "time": float(day),
                    "kind": "stock",
                    "entities": [p],
                    "value": stock.get(p, 0.0),
                    "src": []
                })

    return all_outcomes
